package com.dimlight;

import java.awt.Color;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(DimLightConfig.GROUP)
public interface DimLightConfig extends Config
{
	String GROUP = "dimlight";

	@ConfigSection(
		name = "Hotkeys",
		description = "Keyboard shortcuts",
		position = 10
	)
	String hotkeysSection = "hotkeys";

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "darkness",
		name = "Darkness (%)",
		description = "0 = no change, 100 = fully black",
		position = 1
	)
	default int darkness()
	{
		return 50;
	}

	@ConfigItem(
		keyName = "tint",
		name = "Overlay color",
		description = "Black is the default; use a dark blue or red tint if you prefer",
		position = 2
	)
	default Color tint()
	{
		return Color.BLACK;
	}

	@ConfigItem(
		keyName = "dimInterface",
		name = "Dim interface too",
		description = "Also darkens the inventory, chatbox, minimap and other interface elements",
		position = 3
	)
	default boolean dimInterface()
	{
		return false;
	}

	@ConfigItem(
		keyName = "smoothTransition",
		name = "Smooth transition",
		description = "Fade between darkness levels and when toggling on/off instead of changing instantly",
		position = 4
	)
	default boolean smoothTransition()
	{
		return true;
	}

	@Range(min = 100, max = 2000)
	@ConfigItem(
		keyName = "fadeDuration",
		name = "Fade duration (ms)",
		description = "How long the fade takes",
		position = 5
	)
	default int fadeDuration()
	{
		return 500;
	}

	@ConfigItem(
		keyName = "indicatorMode",
		name = "Level indicator",
		description = "Show the darkness level when it changes: as on-screen text, as a chat message, or both",
		position = 6
	)
	default IndicatorMode indicatorMode()
	{
		return IndicatorMode.ON_SCREEN;
	}

	@Range(min = 500, max = 5000)
	@ConfigItem(
		keyName = "indicatorDuration",
		name = "Indicator duration (ms)",
		description = "How long the on-screen text stays visible",
		position = 7
	)
	default int indicatorDuration()
	{
		return 2000;
	}

	@ConfigItem(
		keyName = "toggleHotkey",
		name = "Toggle on/off",
		description = "Turns the dimming on or off without changing your darkness level",
		section = hotkeysSection,
		position = 11
	)
	default Keybind toggleHotkey()
	{
		return new Keybind(KeyEvent.VK_F12, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "increaseHotkey",
		name = "Darker",
		description = "Increases darkness by the step amount",
		section = hotkeysSection,
		position = 12
	)
	default Keybind increaseHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "decreaseHotkey",
		name = "Lighter",
		description = "Decreases darkness by the step amount",
		section = hotkeysSection,
		position = 13
	)
	default Keybind decreaseHotkey()
	{
		return Keybind.NOT_SET;
	}

	@Range(min = 1, max = 50)
	@ConfigItem(
		keyName = "step",
		name = "Step (%)",
		description = "How much each Darker/Lighter key press changes the darkness",
		section = hotkeysSection,
		position = 14
	)
	default int step()
	{
		return 10;
	}
}

package com.dimlight;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Top-most overlay. Dims the whole canvas (inventory, chatbox, minimap...) when
 * "Dim interface too" is on, then draws the level indicator on top of it.
 */
public class DimLightInterfaceOverlay extends Overlay
{
	private final Client client;
	private final DimLightState state;

	@Inject
	private DimLightInterfaceOverlay(Client client, DimLightState state)
	{
		this.client = client;
		this.state = state;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		if (state.isDimInterface())
		{
			Color color = state.getOverlayColor();
			if (color != null)
			{
				g.setColor(color);
				g.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
			}
		}

		renderIndicator(g);
		return null;
	}

	private void renderIndicator(Graphics2D g)
	{
		String text = state.getIndicatorText();
		if (text == null)
		{
			return;
		}

		int alpha = (int) Math.round(state.getIndicatorOpacity() * 255);
		if (alpha <= 0)
		{
			return;
		}

		Font oldFont = g.getFont();
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();

		int x = client.getViewportXOffset() + (client.getViewportWidth() - fm.stringWidth(text)) / 2;
		int y = client.getViewportYOffset() + 40;

		g.setColor(new Color(0, 0, 0, alpha));
		g.drawString(text, x + 1, y + 1);
		g.setColor(new Color(255, 255, 255, alpha));
		g.drawString(text, x, y);

		g.setFont(oldFont);
	}
}

package com.dimlight;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Dims only the 3D game scene. Drawn above the scene but under the interface. */
public class DimLightOverlay extends Overlay
{
	private final Client client;
	private final DimLightState state;

	@Inject
	private DimLightOverlay(Client client, DimLightState state)
	{
		this.client = client;
		this.state = state;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		// When "Dim interface too" is on, the interface overlay covers everything
		if (client.getGameState() != GameState.LOGGED_IN || state.isDimInterface())
		{
			return null;
		}

		Color color = state.getOverlayColor();
		if (color == null)
		{
			return null;
		}

		g.setColor(color);
		g.fillRect(
			client.getViewportXOffset(),
			client.getViewportYOffset(),
			client.getViewportWidth(),
			client.getViewportHeight()
		);
		return null;
	}
}

package com.dimlight;

import com.google.inject.Provides;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "Dim Light",
	description = "Dim the game screen from 0 to 100% in any area. Works with GPU and 117HD.",
	tags = {"brightness", "dark", "dim", "117hd", "light"}
)
public class DimLightPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private DimLightConfig config;

	@Inject
	private DimLightState state;

	@Inject
	private DimLightOverlay sceneOverlay;

	@Inject
	private DimLightInterfaceOverlay interfaceOverlay;

	private final HotkeyListener toggleHotkey = hotkey(() -> config.toggleHotkey(), this::toggle);
	private final HotkeyListener darkerHotkey = hotkey(() -> config.increaseHotkey(), () -> changeDarkness(config.step()));
	private final HotkeyListener lighterHotkey = hotkey(() -> config.decreaseHotkey(), () -> changeDarkness(-config.step()));

	@Override
	protected void startUp()
	{
		state.refreshSettings();
		state.reset();
		overlayManager.add(sceneOverlay);
		overlayManager.add(interfaceOverlay);
		keyManager.registerKeyListener(toggleHotkey);
		keyManager.registerKeyListener(darkerHotkey);
		keyManager.registerKeyListener(lighterHotkey);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(toggleHotkey);
		keyManager.unregisterKeyListener(darkerHotkey);
		keyManager.unregisterKeyListener(lighterHotkey);
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(interfaceOverlay);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!DimLightConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		state.refreshSettings();

		// Moving the slider: make sure the change is visible and show the level on screen only
		if ("darkness".equals(event.getKey()))
		{
			state.setActive(true);
			announce(false);
		}
	}

	private void toggle()
	{
		state.setActive(!state.isActive());
		announce(true);
	}

	private void changeDarkness(int delta)
	{
		int value = Math.max(0, Math.min(100, config.darkness() + delta));
		state.setActive(true);
		configManager.setConfiguration(DimLightConfig.GROUP, "darkness", value);
		announce(true);
	}

	private void announce(boolean allowChat)
	{
		IndicatorMode mode = config.indicatorMode();
		String text = state.isActive() ? "Dim Light: " + config.darkness() + "%" : "Dim Light: Off";

		if (mode.showsOnScreen())
		{
			state.showIndicator(text, config.indicatorDuration());
		}

		if (allowChat && mode.showsInChat())
		{
			clientThread.invoke(() -> sendChatMessage(text));
		}
	}

	private void sendChatMessage(String text)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append(text)
				.build())
			.build());
	}

	private static HotkeyListener hotkey(Supplier<Keybind> keybind, Runnable action)
	{
		return new HotkeyListener(keybind)
		{
			@Override
			public void hotkeyPressed()
			{
				action.run();
			}
		};
	}

	@Provides
	DimLightConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DimLightConfig.class);
	}
}

package com.dimlight;

import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * State shared by the overlays: whether dimming is on, the current (animated)
 * darkness, and the on-screen level indicator.
 * <p>
 * Config values used while rendering are cached here and refreshed only when the
 * config changes, so nothing allocates or parses settings every frame.
 */
@Singleton
public class DimLightState
{
	private static final long INDICATOR_FADE_OUT_MS = 300;

	private final DimLightConfig config;

	// Cached config values
	private int darknessSetting;
	private Color tint = Color.BLACK;
	private boolean dimInterface;
	private boolean smoothTransition;
	private int fadeDurationMs;

	private boolean active = true;

	// Fade animation, in percent (0-100)
	private double from;
	private double to;
	private double current;
	private long startTime;

	// Last color handed to the overlays, reused while nothing changes
	private Color cachedColor;
	private Color cachedTint;
	private int cachedAlpha = -1;

	// On-screen indicator
	private String indicatorText;
	private long indicatorUntil;

	@Inject
	DimLightState(DimLightConfig config)
	{
		this.config = config;
	}

	public synchronized void refreshSettings()
	{
		darknessSetting = config.darkness();
		tint = config.tint();
		dimInterface = config.dimInterface();
		smoothTransition = config.smoothTransition();
		fadeDurationMs = config.fadeDuration();
	}

	/** Called on plugin start so the dimming fades in from nothing. */
	public synchronized void reset()
	{
		active = true;
		from = 0;
		to = 0;
		current = 0;
		startTime = System.currentTimeMillis();
		indicatorText = null;
	}

	public synchronized boolean isActive()
	{
		return active;
	}

	public synchronized void setActive(boolean active)
	{
		this.active = active;
	}

	public synchronized boolean isDimInterface()
	{
		return dimInterface;
	}

	/** Color to fill with this frame, or null when nothing should be drawn. */
	public synchronized Color getOverlayColor()
	{
		advanceFade();

		int alpha = (int) Math.round(current * 255 / 100);
		if (alpha <= 0)
		{
			return null;
		}

		if (alpha != cachedAlpha || tint != cachedTint)
		{
			cachedColor = new Color(tint.getRed(), tint.getGreen(), tint.getBlue(), alpha);
			cachedAlpha = alpha;
			cachedTint = tint;
		}
		return cachedColor;
	}

	private void advanceFade()
	{
		double target = active ? darknessSetting : 0;

		if (!smoothTransition)
		{
			from = to = current = target;
			return;
		}

		long now = System.currentTimeMillis();
		if (target != to)
		{
			// Target changed: start a new fade from wherever we are right now
			from = current;
			to = target;
			startTime = now;
		}

		if (current == to)
		{
			return;
		}

		double t = Math.min(1.0, (now - startTime) / (double) fadeDurationMs);
		// Smoothstep easing
		current = t >= 1.0 ? to : from + (to - from) * (t * t * (3 - 2 * t));
	}

	public synchronized void showIndicator(String text, int durationMs)
	{
		indicatorText = text;
		indicatorUntil = System.currentTimeMillis() + durationMs;
	}

	/** Text to show on screen, or null if there is nothing to show. */
	public synchronized String getIndicatorText()
	{
		if (indicatorText != null && System.currentTimeMillis() >= indicatorUntil)
		{
			indicatorText = null;
		}
		return indicatorText;
	}

	/** 1.0 while visible, fading to 0.0 during the last moments. */
	public synchronized double getIndicatorOpacity()
	{
		long remaining = indicatorUntil - System.currentTimeMillis();
		return Math.max(0, Math.min(1.0, remaining / (double) INDICATOR_FADE_OUT_MS));
	}
}

package com.dimlight;

public enum IndicatorMode
{
	OFF("Off", false, false),
	ON_SCREEN("On screen", true, false),
	CHAT("Chat", false, true),
	BOTH("Chat + on screen", true, true);

	private final String label;
	private final boolean onScreen;
	private final boolean chat;

	IndicatorMode(String label, boolean onScreen, boolean chat)
	{
		this.label = label;
		this.onScreen = onScreen;
		this.chat = chat;
	}

	public boolean showsOnScreen()
	{
		return onScreen;
	}

	public boolean showsInChat()
	{
		return chat;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

